class AdditionalServicesDialogController{jobId;constructor($mdDialog,$http,jobId,clientId,speedId){this._$mdDialog=$mdDialog;this._$http=$http;this._jobId=jobId;this._clientId=clientId;this._speedId=speedId;this.isLoading=false;this.query={order:"name",limit:5,page:1};this.additionalServices=[];this.totalServicesCount=0;this.getServices(clientId,speedId,jobId,this.query).then(serviceResponse=>{this.additionalServices=serviceResponse.items;this.totalServicesCount=serviceResponse.totalCount})}async getServices(){const url="job/GetAllClientItemsBySpeed";let response=await this._$http.get(url+"?clientId="+this._clientId+"&speedId="+this._speedId+"&jobId="+this._jobId+"&pageNumber="+this.query.limit+"&pageSize="+this.query.page);return response.data}getTotal(){return 1}async bookServices(allJobServices){}cancel(){this._$mdDialog.cancel()}}